import React, { useRef, useEffect, useState } from "react";

function CanvasBoard({ socket }) {
  const canvasRef = useRef(null);
  const ctxRef = useRef(null);

  const [text, setText] = useState("");
  const [textPosition, setTextPosition] = useState(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    canvas.width = window.innerWidth - 200;
    canvas.height = window.innerHeight - 80;
    const ctx = canvas.getContext("2d");
    ctx.lineCap = "round";
    ctx.strokeStyle = "black";
    ctx.lineWidth = 2;
    ctx.font = "20px Arial";        // Set font here
    ctxRef.current = ctx;
  }, []);

  const handleCanvasClick = (e) => {
    // Get click position
    setTextPosition({ x: e.nativeEvent.offsetX, y: e.nativeEvent.offsetY });
  };

  const addTextToCanvas = () => {
    if (!textPosition || !text) return;
    const ctx = ctxRef.current;
    ctx.fillText(text, textPosition.x, textPosition.y);
    socket.emit("addText", { text, x: textPosition.x, y: textPosition.y });
    setText("");
    setTextPosition(null);
  };

  useEffect(() => {
    socket.on("addText", ({ text, x, y }) => {
      const ctx = ctxRef.current;
      ctx.fillText(text, x, y);
    });
  }, [socket]);

  return (
    <div>
      <canvas
        ref={canvasRef}
        onClick={handleCanvasClick}
        className="border bg-white"
      />
      <input
        type="text"
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Enter text"
      />
      <button onClick={addTextToCanvas} disabled={!text || !textPosition}>
        Add Text
      </button>
    </div>
  );
}

export default CanvasBoard;
